using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;

public sealed partial class CompanionWindow {
    double? TrainingBest(out string context){
        var profile=CompetitionProfiles.Selected(settings);var caches=profile==null?new CachedSnapshot[0]:new[]{CompanionStore.Read<CachedSnapshot>(Path.Combine(CompetitionProfiles.DataDirectory(profile),"leaderboard-cache.json")),CompanionStore.Read<CachedSnapshot>(Path.Combine(CompetitionProfiles.DataDirectory(profile),"cache.json"))};
        return GtcDataPriority.TrainingBest(driver.Text,DateTime.UtcNow-trainingRecords.LatestUtc<=TimeSpan.FromSeconds(3)?trainingRecords.Latest:null,caches,driverHistoryService.Collector.Book.Records,profile==null?0:profile.TimingId,trainingRecords.Book,out context);
    }
    void ShowTrainingHelp(Action<double> apply,bool active){using(var dialog=CreateTrainingHelp(apply,active))dialog.ShowDialog(this);}
    Form CreateTrainingHelp(Action<double> apply,bool active,double? example=null){
        string context;double? known=TrainingBest(out context);if(example.HasValue){known=example;context="Exemplo de cálculo";}
        var dialog=new Form{Text="Preparar um stint",Icon=BrandIcon(),BackColor=GtcTheme.Background,ForeColor=GtcTheme.Text,Font=F(12),AutoScaleMode=AutoScaleMode.None,StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(P(540),P(610)),MinimumSize=new Size(P(500),P(450)),MinimizeBox=false,MaximizeBox=false};
        var stack=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1,Padding=new Padding(P(18))};stack.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};scroll.Controls.Add(stack);dialog.Controls.Add(scroll);
        Action<string,int,bool> text=(value,size,bold)=>{var label=TextLabel(value,size,bold);label.MaximumSize=new Size(P(475),0);label.Margin=new Padding(0,0,0,P(12));stack.Controls.Add(label);};
        text("Ritmo de corrida a partir da melhor volta",16,true);
        text("Alvo = melhor volta válida × (1 + margem / 100).",12,true);
        text("A referência dá prioridade à classificação e às voltas válidas disponíveis na GTC. Os tempos locais servem de apoio quando falta informação online. Confirma a origem, a pista e as condições indicadas antes de aplicar o alvo.",11,false);
        text("Como estimativa inicial, experimenta acrescentar 0,5–1,0% ao tempo. A sugestão rápida usa 0,5% para o alvo e 0,6% da melhor volta para a janela ±, arredondada a centésimos (mínimo 0,10 s). É uma margem ajustável, não uma regra universal: combustível, pneus, temperatura e tráfego alteram o ritmo. Confirma o alvo com a média de 10–15 voltas nas condições da corrida.",11,false);
        var calculator=new TableLayoutPanel{AutoSize=true,Dock=DockStyle.Top,ColumnCount=2,BackColor=GtcTheme.Surface,Padding=new Padding(P(12)),Margin=new Padding(0,0,0,P(12))};calculator.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,65));calculator.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,35));stack.Controls.Add(calculator);
        calculator.Controls.Add(TextLabel("Melhor volta válida",11),0,0);calculator.Controls.Add(TextLabel("Margem (%)",11),1,0);
        var best=new TextBox{Text=known.HasValue?TimingData.Lap(known.Value):"",Font=F(12),BackColor=GtcTheme.Input,ForeColor=GtcTheme.Text,BorderStyle=BorderStyle.FixedSingle,Dock=DockStyle.Top,Margin=new Padding(0,P(6),P(12),P(8)),AccessibleName="Melhor volta válida para calcular ritmo de corrida"};var margin=new NumericUpDown{Minimum=0,Maximum=10,DecimalPlaces=2,Increment=.1m,Value=.5m,Font=F(12),BackColor=GtcTheme.Input,ForeColor=GtcTheme.Text,Dock=DockStyle.Top,Margin=new Padding(0,P(6),0,P(8)),AccessibleName="Margem percentual sobre a melhor volta"};calculator.Controls.Add(best,0,1);calculator.Controls.Add(margin,1,1);
        var source=TextLabel(context,10);source.ForeColor=GtcTheme.Muted;source.MaximumSize=new Size(P(445),0);calculator.Controls.Add(source,0,2);calculator.SetColumnSpan(source,2);
        var result=TextLabel("",14,true);result.ForeColor=GtcTheme.Accent;result.Margin=new Padding(0,P(10),0,P(10));calculator.Controls.Add(result,0,3);calculator.SetColumnSpan(result,2);
        var use=Button("Aplicar ao próximo stint",245,true);use.Enabled=!active;calculator.Controls.Add(use,0,4);calculator.SetColumnSpan(use,2);double calculated=0;
        bool edited=false,loading=false;Action calculate=()=>{double lap;if(!TrainingMath.ParsePace(best.Text,out lap)){result.Text="Usa o formato m:ss,mmm.";use.Enabled=false;return;}try{calculated=TrainingMath.RacePace(lap,(double)margin.Value);result.Text="Alvo "+TimingData.Lap(calculated)+" · "+TrainingMath.Delta(calculated-lap);use.Enabled=!active;}catch(Exception ex){result.Text=ex.Message;use.Enabled=false;}};best.TextChanged+=(s,e)=>{if(!loading){edited=true;source.Text="Referência editável · confirma a pista e as condições.";}calculate();};margin.ValueChanged+=(s,e)=>calculate();calculate();
        dialog.Shown+=async(s,e)=>{if(PreviewOnly||example.HasValue)return;await history.Collect(settings);if(dialog.IsDisposed||edited)return;string refreshedContext;var refreshed=TrainingBest(out refreshedContext);if(refreshed.HasValue){loading=true;best.Text=TimingData.Lap(refreshed.Value);source.Text=refreshedContext;loading=false;}};
        use.Click+=(s,e)=>{apply(calculated);dialog.Close();};
        if(active)text("Termina o stint em curso para aplicar outro alvo.",11,false);
        text("Como configurar o stint",14,true);
        text("1. Abre o rFactor e prepara o combustível, pneus e condições que vais usar na corrida.\n2. Em Overlay → Stint, escolhe Voltas ou Minutos e a duração.\n3. Aceita a sugestão ou introduz o ritmo alvo e a janela ± de consistência — por exemplo, 1:22,700 ±0,50 s marca 1:22,200 a 1:23,200. Voltas mais rápidas que 1:22,200 também contam na janela.\n4. Carrega em Iniciar stint antes da passagem pela meta. A volta de saída fica de fora.\n5. Nos treinos por minutos, termina a volta em que o tempo chega a zero. No final, consulta o gráfico e a média de todas as voltas completas, incluindo inválidas.",11,false);
        text("Nota do stint · 0 a 100",14,true);
        text("70 pontos de ritmo + 30 de limpeza. Uma média até ao alvo + tolerância recebe 70 pontos; mais rápido mantém a pontuação máxima. Acima desse limite, o ritmo perde pontos de forma linear e chega a zero quando a diferença adicional atinge 5% do alvo. A média inclui voltas inválidas.\nA limpeza perde 10 pontos por cada saída por 10 voltas, até perder os 30 pontos. Exemplo: 15 voltas no ritmo e 1 saída dão 93/100; 3 saídas dão 80/100. A nota é arredondada ao inteiro mais próximo.\nA nota é provisória durante o treino e parcial se terminares antes do objetivo. Falhas de telemetria tornam a avaliação estimada. Sem voltas, não há nota. As saídas são estimativas locais, não penalizações oficiais nem rating GTC.",11,false);
        text("Dois overlays, controlos comuns",14,true);
        text("O overlay de stint acompanha duração, média e consistência. O overlay GTC mantém a classificação e os recordes. Em Overlay → Aparência, a transparência e os botões Mostrar e Mover aplicam-se aos dois; os atalhos de visibilidade, movimento e vista também atuam em conjunto. Podes arrastar cada um para uma posição própria. As voltas locais são usadas como apoio quando faltam dados da mesma sessão na GTC; os registos anteriores são preservados.",11,false);
        text("As saídas são estimadas pela posição do carro e não equivalem às penalizações oficiais. Uma falha de telemetria pode tornar uma volta incompleta para efeitos de recordes.",10,false);
        text("Gráficos dos outros pilotos",14,true);
        text("Escolhe Volta completa ou Setor 1/2/3 no gráfico. Na volta completa, verde identifica tempos dentro do alvo ± tolerância; verde carregado identifica voltas abaixo do limite rápido, que também contam na janela; vermelho significa acima do limite lento. Num setor, verde significa igual ou mais rápido e vermelho mais lento que o mesmo setor da melhor volta limpa da seleção. Uma cruz marca invalidade/dados incompletos. Os setores ausentes ficam sem tempo, não são calculados dividindo a volta.",11,false);
        text("Em Overlay → Stint → Pilotos e stints, escolhe o piloto, a sessão e o stint. Clica num ponto para consultar essa volta e comparar os três setores. As linhas PIT assinalam boxes; ~ indica um limite aproximado. A média limpa usa apenas voltas válidas, sem boxes e com dados completos. Podes incluir as outras voltas. Voltas em falta não se transformam em paragens.",11,false);
        text("A GTC tem prioridade nos gráficos. Os registos locais apenas complementam voltas em falta de uma sessão confirmada; sem correspondência segura o gráfico aguarda dados da GTC. A cruz também identifica voltas possivelmente inválidas ou incompletas: consulta o ponto para distinguir. O composto e os valores de pneus disponíveis aparecem discretamente no gráfico; dados nulos não são apresentados como desgaste confirmado. Atualizar GTC consulta o histórico online disponível, que pode estar incompleto. A recolha local de apoio fica neste PC.",11,false);
        var close=Button("Fechar",110);stack.Controls.Add(close);close.Click+=(s,e)=>dialog.Close();GtcWindowTheme.Attach(dialog);return dialog;
    }
    public void RenderTrainingHelp(string destination){using(var dialog=CreateTrainingHelp(value=>{},false,82.247)){dialog.ShowInTaskbar=false;dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-20000,-20000);dialog.Show();Application.DoEvents();using(var bitmap=new Bitmap(dialog.ClientSize.Width,dialog.ClientSize.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(Point.Empty,dialog.ClientSize));bitmap.Save(destination);}dialog.Close();}}
}
